package com.tekwatt.reporting.service;
import com.fasterxml.jackson.databind.*;import com.tekwatt.reporting.entity.ReportType;import java.nio.charset.StandardCharsets;import java.util.*;import org.springframework.stereotype.Component;
@Component public class CsvReportGenerator {private final ObjectMapper mapper;public CsvReportGenerator(ObjectMapper mapper){this.mapper=mapper;}public byte[] generate(ReportType type,JsonNode data){List<JsonNode> rows=new ArrayList<>();if(type==ReportType.DAILY&&data.isArray())data.forEach(rows::add);else rows.add(data);if(rows.isEmpty())return new byte[0];LinkedHashSet<String> headers=new LinkedHashSet<>();rows.forEach(row->row.fieldNames().forEachRemaining(headers::add));StringBuilder csv=new StringBuilder();csv.append(String.join(",",headers)).append('\n');for(JsonNode row:rows){int index=0;for(String header:headers){if(index++>0)csv.append(',');csv.append(escape(row.path(header).isMissingNode()?"":row.path(header).asText()));}csv.append('\n');}return csv.toString().getBytes(StandardCharsets.UTF_8);}private String escape(String value){String safe=value.replace("\"","\"\"");return safe.contains(",")||safe.contains("\"")||safe.contains("\n")?'"'+safe+'"':safe;}}
